font-size:12px;font-weight:600;color:var(--text-muted);background:var(--surface-hover,var(--surface))}.lgs-table td{font-size:13px}.lgs-table tr:hover td{background:var(--surface-hover,transparent)}.lgs-muted{color:var(--text-muted);font-size:13px}.lgs-table{width:100%;border-collapse:collapse}.lgs-table th,.lgs-table td{text-align:left;padding:8px;border-bottom:1px solid var(--border);vertical-align:middle}.lgs-table input,.lgs-table select{max-width:100%}.lgs-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.lgs-msg{padding:10px;border:1px solid var(--border);border-radius:8px;margin:12px 0}.lgs-inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.lgs-inline input{min-width:150px}.lgs-inline select{min-width:140px}@media(max-width:750px){.lgs-grid{grid-template-columns:1fr}.lgs-table{font-size:13px}.lgs-table th,.lgs-table td{padding:5px}}
