<main class="lgs-wrap"><?php if (!$embed): ?><div class="lgs-actions"><div style="flex:1"><h1 style="margin:0 0 5px"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_title')); ?></h1><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_intro')); ?></p></div><a class="btn btn-secondary" href="index.php"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.back_to_logistics')); ?></a></div><?php endif; ?>
