<h3><?php echo htmlspecialchars(I18n::t('asset-management.logistics.add_purpose')); ?></h3><form id="lgsAddPurpose" class="lgs-add-row"><select name="movement_type" aria-label="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.movement_type_aria')); ?>"><option value="outbound_dispatch"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.outbound_dispatch')); ?></option><option value="inbound_return"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.inbound_return')); ?></option></select><input name="name" maxlength="100" required placeholder="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.purpose_name_placeholder')); ?>"><input name="display_order" type="number" min="0" value="50" required aria-label="<?php echo htmlspecialchars(I18n::t('asset-management.logistics.display_order_aria')); ?>"><button class="btn btn-primary" type="submit"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.add_purpose_button')); ?></button></form></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.carriers_title')); ?></h2><div class="lgs-field"><label for="lgsCarrierSearch">Add carrier from Suppliers</label><div class="lgs-picker"><input id="lgsCarrierSearch" type="search" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="lgsCarrierMatches" minlength="2" placeholder="Type to search suppliers"><div id="lgsCarrierMatches" class="lgs-picker-menu" role="listbox" hidden></div></div><p class="lgs-muted">Choose a supplier to add it as a carrier.</p></div><div id="lgsCarriers"></div></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.completion_behaviour')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_policy_intro')); ?></p><div class="lgs-grid" id="lgsPolicies"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.loading_policies_text')); ?></div><div class="lgs-actions"><button id="lgsSavePolicies" class="btn btn-primary" type="button"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.save_policies_button')); ?></button></div></section>
<section class="lgs-card"><h2><?php echo htmlspecialchars(I18n::t('asset-management.logistics.inspection_outcome_mapping')); ?></h2><p class="lgs-muted"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.settings_outcome_intro')); ?></p><div id="lgsOutcomes"></div><div class="lgs-actions"><button id="lgsSaveOutcomes" class="btn btn-primary" type="button"><?php echo htmlspecialchars(I18n::t('asset-management.logistics.save_outcomes_button')); ?></button></div></section>
</main>
<script>
(function(){
 const labels={status:'Status',actions:'Actions',customized:'Customized',shared_default:'Shared default',company_purpose:'Company purpose',restore_shared_default:'Restore default',restore_shared_default_confirm:'Restore the shared purpose? Your company-specific changes will be discarded.',shared_default_restored:'Shared default restored.'};
 const tr=(key)=>((window.translations||{})['asset-management']||{}).logistics?.[key]||labels[key]||key;
 const api='../../api/assets/logistics.php', msg=document.getElementById('lgsMessage'); let cfg=null;
 const types=[['outbound_dispatch',tr('outbound_dispatch')],['inbound_return',tr('inbound_return')]];
 const outcomes=[['passed',tr('passed')],['minor_wear',tr('minor_wear')],['damaged',tr('damaged')],['scrap',tr('scrap')]];
 function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function say(s,bad=false){msg.hidden=false;msg.textContent=s;msg.style.borderColor=bad?'var(--danger,#c33)':'var(--border)';}
 async function call(action,data={}){const r=await fetch(api,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})});let j;try{j=await r.json()}catch(e){throw new Error(tr('unexpected_server_response'));}if(!r.ok||!j.success)throw new Error(j.error||tr('request_failed'));return j;}
 function statusOptions(selected){return '<option value="">'+tr('status_not_change')+'</option>'+cfg.statuses.map(s=>'<option value="'+Number(s.id)+'" '+(String(selected||'')===String(s.id)?'selected':'')+'>'+esc(s.name)+'</option>').join('');}
 function renderPurposes(){document.getElementById('lgsPurposes').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('type')+'</th><th>'+tr('name')+'</th><th>'+tr('order')+'</th><th>'+tr('active')+'</th><th>'+tr('status')+'</th><th>'+tr('actions')+'</th></tr></thead><tbody>'+cfg.purposes.map(p=>{const shared=p.tenant_id==null,override=Number(p.override_of_id||0)>0;return '<tr data-purpose="'+Number(p.id)+'"><td>'+esc(p.movement_type==='outbound_dispatch'?tr('outbound_short'):tr('inbound_short'))+'</td><td><input name="name" maxlength="100" value="'+esc(p.name)+'" aria-label="'+tr('purpose_name_aria')+'" '+'></td><td><input name="display_order" type="number" min="0" value="'+Number(p.display_order)+'" style="width:80px" aria-label="'+tr('purpose_order_aria')+'" '+'></td><td><input name="is_active" type="checkbox" '+(Number(p.is_active)?'checked':'')+' aria-label="'+tr('purpose_active_aria')+'" '+'></td><td><span class="lgs-tag">'+(override?tr('customized'):shared?tr('shared_default'):tr('company_purpose'))+'</span></td><td><div class="lgs-purpose-actions"><button type="button" class="btn btn-secondary" data-save-purpose="'+Number(p.id)+'">'+tr('save_purpose_button')+'</button>'+(override?'<button type="button" class="btn btn-secondary" data-reset-purpose="'+Number(p.id)+'">'+tr('restore_shared_default')+'</button>':'')+'</div></td></tr>';}).join('')+'</tbody></table>';
 document.querySelectorAll('[data-reset-purpose]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm(tr('restore_shared_default_confirm')))return;try{await call('reset_purpose_override',{id:Number(b.dataset.resetPurpose)});await load();say(tr('shared_default_restored'));}catch(e){say(e.message,true);}}));
 document.querySelectorAll('[data-save-purpose]').forEach(b=>b.addEventListener('click',async()=>{const row=b.closest('tr'),id=Number(b.dataset.savePurpose),p=cfg.purposes.find(x=>Number(x.id)===id);try{await call('save_purpose',{id,movement_type:p.movement_type,original_movement_type:p.movement_type,name:row.querySelector('[name=name]').value,display_order:Number(row.querySelector('[name=display_order]').value),is_active:row.querySelector('[name=is_active]').checked?1:0});await load();say(tr('purpose_saved'));}catch(e){say(e.message,true);}}));}
 function renderPolicies(){const map={};cfg.policies.forEach(p=>map[p.movement_type]=p);document.getElementById('lgsPolicies').innerHTML=types.map(([type,label])=>{const p=map[type]||{};const update=type==='outbound_dispatch'&&Number(p.update_asset_status_on_completion||0)===1;return '<div class="lgs-card" style="margin:0"><h3>'+label+'</h3><input type="hidden" name="movement_type" value="'+type+'"><div class="lgs-field"><label><input type="checkbox" name="close_movement_on_completion" '+(p.close_movement_on_completion==null||Number(p.close_movement_on_completion)===1?'checked':'')+'>'+tr('completion_close_help')+'</label></div>'+(type==='inbound_return'?'<div class="lgs-field"><label>Asset assignment on completion</label><div class="lgs-policy-note">The asset will be unassigned from its current user when the inbound return is completed. This happens automatically; no separate setting is needed.</div></div>':'<div class="lgs-field"><label><input type="checkbox" name="assign_to_recipient_on_ack" '+(p.assign_to_recipient_on_ack==null||Number(p.assign_to_recipient_on_ack)===1?'checked':'')+'>'+tr('assign_after_ack_help')+'</label><span class="lgs-muted">'+tr('assign_policy_detail')+'</span></div>')+'<div class="lgs-field"><label><input type="checkbox" name="update_asset_status_on_completion" '+(update?'checked':'')+' '+(type==='inbound_return'?'disabled':'')+'>'+tr('status_update_label')+'</label></div><div class="lgs-field"><label>'+tr('status_to_apply_label')+'</label><select name="completion_asset_status_id" '+(update?'':'disabled')+' '+(type==='inbound_return'?'disabled':'')+'>'+statusOptions(p.completion_asset_status_id)+'</select><span class="lgs-muted">'+(type==='inbound_return'?tr('return_status_policy_detail'):tr('status_update_policy_detail'))+'</span></div><div class="lgs-field"><label>Inspection after receipt</label><p class="lgs-muted">Choose whether a returned asset must be inspected before the return can be completed. The inspector records an outcome such as Passed, Minor wear, Damaged or Scrap.</p><select name="post_receipt_action"><option value="none" '+((p.post_receipt_action||'none')==='none'?'selected':'')+'>'+tr('inspection_not_required_label')+'</option><option value="inspection" '+(p.post_receipt_action==='inspection'?'selected':'')+'>'+tr('inspection_required_label')+'</option></select></div><div class="lgs-field"><label>How is the inspection performed?</label><p class="lgs-muted">Manual means an authorised staff member records the inspection result in FreeITSM. No external inspection integration is configured.</p><select name="inspection_provider" '+(p.post_receipt_action==='inspection'?'':'disabled')+'><option value="">'+tr('inspection_method_choose')+'</option><option value="manual" '+(p.inspection_provider==='manual'?'selected':'')+'>'+tr('manual_inspection_available')+'</option></select></div></div>';}).join('');document.querySelectorAll('#lgsPolicies [name=update_asset_status_on_completion]').forEach(el=>el.addEventListener('change',()=>{el.closest('.lgs-card').querySelector('[name=completion_asset_status_id]').disabled=!el.checked;}));document.querySelectorAll('#lgsPolicies [name=post_receipt_action]').forEach(el=>el.addEventListener('change',()=>{el.closest('.lgs-card').querySelector('[name=inspection_provider]').disabled=el.value!=='inspection';}));}
 function renderCarriers(){const rows=cfg.carriers||[];document.getElementById('lgsCarriers').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('carrier_supplier')+'</th><th>'+tr('enabled')+'</th><th>'+tr('default')+'</th><th>'+tr('tracking_url_air')+'</th><th>'+tr('tracking_url_surface')+'</th><th></th></tr></thead><tbody>'+rows.map(c=>'<tr data-carrier="'+Number(c.supplier_id)+'"><td>'+esc(c.name)+'</td><td><input type="checkbox" name="enabled" '+(Number(c.carrier_active)?'checked':'')+'></td><td><input type="radio" name="defaultCarrier" '+(Number(c.is_default)?'checked':'')+' '+(Number(c.carrier_active)?'':'disabled')+'></td><td><input name="tracking_url_air" maxlength="1000" style="min-width:240px" placeholder="https://carrier.example/air-track" value="'+esc(c.tracking_url_air||'')+'"></td><td><input name="tracking_url_surface" maxlength="1000" style="min-width:240px" placeholder="https://carrier.example/track?ref={tracking_number}" value="'+esc(c.tracking_url_surface||'')+'"></td><td><button type="button" class="btn btn-secondary" data-save-carrier="'+Number(c.supplier_id)+'">Save</button></td></tr>').join('')+'</tbody></table><p class="lgs-muted">'+tr('tracking_url_placeholder_hint')+'</p>';
 document.querySelectorAll('[data-save-carrier]').forEach(b=>b.addEventListener('click',async()=>{const row=b.closest('tr'),supplier_id=Number(b.dataset.saveCarrier),is_default=!!row.querySelector('[name=defaultCarrier]').checked;try{await call('save_carrier',{supplier_id,is_active:row.querySelector('[name=enabled]').checked?1:0,is_default:is_default?1:0,tracking_url_air:row.querySelector('[name=tracking_url_air]').value,tracking_url_surface:row.querySelector('[name=tracking_url_surface]').value});await load();say(tr('carrier_saved'));}catch(e){say(e.message,true);}}));}
 function renderOutcomes(){const map={};cfg.outcome_statuses.forEach(o=>map[o.outcome_code]=o.asset_status_id);document.getElementById('lgsOutcomes').innerHTML='<table class="lgs-table"><thead><tr><th>'+tr('outcome')+'</th><th>'+tr('asset_status')+'</th></tr></thead><tbody>'+outcomes.map(([code,label])=>'<tr><td>'+label+'</td><td><select data-outcome="'+code+'">'+statusOptions(map[code])+'</select></td></tr>').join('')+'</tbody></table>';}
 async function load(){cfg=await call('get_configuration');renderPurposes();renderPolicies();renderOutcomes();renderCarriers();}
 const carrierInput=document.getElementById('lgsCarrierSearch'), carrierMenu=document.getElementById('lgsCarrierMatches');let carrierTimer=null,carrierRequest=0;
 function closeCarrierMenu(){carrierMenu.hidden=true;carrierInput.setAttribute('aria-expanded','false');}
 async function searchCarrierPicker(){const q=carrierInput.value.trim(),request=++carrierRequest;if(q.length<2){carrierMenu.innerHTML='';closeCarrierMenu();return;}carrierMenu.hidden=false;carrierInput.setAttribute('aria-expanded','true');carrierMenu.innerHTML='<div class="lgs-picker-option">Searching…</div>';try{const result=await call('search_carrier_suppliers',{query:q});if(request!==carrierRequest)return;const rows=result.suppliers||[];carrierMenu.innerHTML=rows.length?rows.map(s=>'<button type="button" class="lgs-picker-option" role="option" data-add-carrier="'+Number(s.id)+'" data-name="'+esc(s.name)+'">'+esc(s.name)+'</button>').join(''):'<div class="lgs-picker-option">No matching suppliers found.</div>';carrierMenu.querySelectorAll('[data-add-carrier]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await call('save_carrier',{supplier_id:Number(b.dataset.addCarrier),is_active:1,is_default:(cfg.carriers||[]).length?0:1,tracking_url_air:'',tracking_url_surface:''});carrierInput.value='';closeCarrierMenu();await load();say(b.dataset.name+' added as a carrier.');}catch(e){say(e.message,true);b.disabled=false;}}));}catch(e){if(request===carrierRequest){carrierMenu.textContent=e.message;carrierMenu.hidden=false;}}}
 carrierInput.addEventListener('input',()=>{clearTimeout(carrierTimer);carrierTimer=setTimeout(searchCarrierPicker,250);});carrierInput.addEventListener('focus',()=>{if(carrierInput.value.trim().length>=2)searchCarrierPicker();});document.addEventListener('click',e=>{if(!e.target.closest('.lgs-picker'))closeCarrierMenu();});carrierInput.addEventListener('keydown',e=>{if(e.key==='Escape')closeCarrierMenu();if(e.key==='ArrowDown'){const first=carrierMenu.querySelector('button');if(first){e.preventDefault();first.focus();}}});
 document.getElementById('lgsAddPurpose').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const submit=e.currentTarget.querySelector('button[type=submit]');submit.disabled=true;submit.textContent='Saving…';await call('save_purpose',{movement_type:f.get('movement_type'),name:f.get('name'),display_order:Number(f.get('display_order')),is_active:1});e.currentTarget.reset();await load();say(tr('purpose_added'));}catch(err){say(err.message,true);}});
 document.getElementById('lgsSavePolicies').addEventListener('click',async()=>{try{for(const card of document.querySelectorAll('#lgsPolicies .lgs-card')){const get=n=>card.querySelector('[name="'+n+'"]');await call('save_receipt_policy',{movement_type:get('movement_type').value,post_receipt_action:get('post_receipt_action').value,inspection_provider:get('inspection_provider').value,close_movement_on_completion:get('close_movement_on_completion').checked?1:0,assign_to_recipient_on_ack:get('assign_to_recipient_on_ack').checked?1:0,update_asset_status_on_completion:get('update_asset_status_on_completion').checked?1:0,completion_asset_status_id:get('completion_asset_status_id').value||null});}await load();say(tr('policies_saved'));}catch(e){say(e.message,true);}});
 document.getElementById('lgsSaveOutcomes').addEventListener('click',async()=>{try{for(const sel of document.querySelectorAll('[data-outcome]'))await call('save_outcome_status',{outcome_code:sel.dataset.outcome,asset_status_id:sel.value||null});await load();say(tr('outcomes_saved'));}catch(e){say(e.message,true);}});
 load().catch(e=>say(e.message,true));
})();
</script><?php if (!$embed): ?></body></html><?php else: ?></div><?php endif; ?>
